import React from "react";
import { palette } from "../theme/palette";
import { Earrings, Head, HeadBack, MaangTikka, Nath } from "./parts/Head";
import { Arm, type ArmSpec } from "./parts/Limbs";
import { outfitLayers } from "./parts/Outfits";
import { DiagramCard, GameConsole, Laptop } from "./parts/HeldProps";
import { REST, type HeldProp, type Outfit, type Person, type Pose } from "./types";

/*
 * <Character person={people.rishabh} outfit={wardrobe.rishabh.wedding} height={700} />
 * Front-facing illustrated figure in a 400×1000 space; feet rest on y≈955.
 */

const Safa: React.FC<{ color: string; stripe: string }> = ({ color, stripe }) => (
  <g>
    <path d="M144 106 C134 60 164 18 202 16 C244 14 270 52 258 106 C250 91 236 83 222 81 C206 79 192 79 178 81 C164 83 152 91 144 106 Z" fill={color} />
    <path d="M144 106 C134 60 164 18 202 16 C244 14 270 52 258 106 C250 91 236 83 222 81 C206 79 192 79 178 81 C164 83 152 91 144 106 Z" fill="url(#dots-gold)" />
    <path d="M144 106 C134 60 164 18 184 17 C166 40 158 70 158 92 C152 96 147 100 144 106 Z" fill="#000" opacity={0.14} />
    <g fill="none" strokeLinecap="round">
      <path d="M146 92 C172 68 226 48 258 72" stroke={stripe} strokeWidth={4} />
      <path d="M150 74 C178 50 228 34 254 50" stroke={stripe} strokeWidth={2.4} />
      <path d="M160 46 C186 28 224 22 244 32" stroke={stripe} strokeWidth={1.6} />
      <path d="M144 106 C160 90 186 81 202 81 C218 81 242 88 258 106" stroke="url(#foil)" strokeWidth={3} />
    </g>
    {/* turra fan */}
    <path d="M170 26 C156 8 162 -8 178 -12 C176 2 178 14 184 24 Z" fill={color} stroke="url(#foil)" strokeWidth={1.4} />
    {/* sarpech brooch, pearl drop and plume */}
    <path d="M214 54 C206 26 214 -4 236 -20 C236 4 230 28 222 56 Z" fill="#FAF6EE" />
    <path d="M216 50 C214 26 222 4 234 -14" fill="none" stroke="#C9C1B2" strokeWidth={1.2} />
    <path d="M198 64 C210 76 228 78 244 70" fill="none" stroke="#F6F0E4" strokeWidth={3.2} strokeDasharray="0.1 6" strokeLinecap="round" />
    <circle cx={216} cy={60} r={10} fill="url(#foil)" />
    <circle cx={216} cy={60} r={5} fill={palette.maroonLight} />
    <circle cx={214} cy={58} r={1.6} fill="#FFFFFF" opacity={0.7} />
  </g>
);

/** Sehra: strands of pearls and jasmine falling from the safa rim; `drop` 0→1 lowers them. */
const Sehra: React.FC<{ drop: number }> = ({ drop }) => {
  const strands = [];
  for (let x = 146; x <= 254; x += 7) {
    const edge = 1 - Math.pow((x - 200) / 58, 2);
    const len = (70 + edge * 60) * drop;
    const y0 = 100 - edge * 16;
    strands.push(
      <g key={x}>
        <path d={`M${x} ${y0} L${x} ${y0 + len}`} stroke="#E9DFC8" strokeWidth={0.8} />
        <path d={`M${x} ${y0 + 4} L${x} ${y0 + len}`} stroke={x % 14 === 0 ? "#F7F2E6" : "#FFFDF6"} strokeWidth={4.2} strokeDasharray="0.1 7" strokeLinecap="round" />
        {len > 20 ? <circle cx={x} cy={y0 + len + 2} r={2.6} fill={x % 21 === 0 ? palette.maroonLight : "url(#foil)"} /> : null}
      </g>,
    );
  }
  return (
    <g>
      <path d="M142 100 C162 86 186 82 200 82 C214 82 238 86 258 100" fill="none" stroke="url(#foil)" strokeWidth={5} opacity={Math.min(1, drop * 3)} />
      {strands}
    </g>
  );
};

const VeilFront: React.FC<{ color: string }> = ({ color }) => (
  <g>
    <path d="M142 118 C134 64 164 26 200 24 C236 26 266 64 258 118 C252 86 232 62 200 60 C168 62 148 86 142 118 Z" fill={color} opacity={0.22} />
        <path d="M142 118 C148 86 168 62 200 60 C232 62 252 86 258 118" fill="none" stroke="url(#foil)" strokeWidth={4} />
    <path d="M146 112 C152 84 170 66 200 64 C230 66 248 84 254 112" fill="none" stroke="url(#foil)" strokeWidth={4} strokeDasharray="0.1 8" strokeLinecap="round" />
  </g>
);

const HELD: Record<HeldProp, React.ReactNode> = {
  laptop: <g transform="scale(1.55)"><Laptop /></g>,
  diagram: <g transform="scale(1.6)"><DiagramCard /></g>,
  console: <g transform="scale(1.4)"><GameConsole /></g>,
};

export const Character: React.FC<{
  person: Person;
  outfit: Outfit;
  pose?: Partial<Pose>;
  holding?: HeldProp;
  height?: number;
  pins?: boolean;
  /** 0→1 lowers the groom's sehra (only with a safa). */
  sehra?: number;
  style?: React.CSSProperties;
}> = ({ person: p, outfit: o, pose, holding, height = 700, pins = true, sehra = 0, style }) => {
  const ps = { ...REST, ...pose };
  const female = p.face === "female";
  const layers = outfitLayers(o, p);
  const bridal = o.kind === "lehenga" && o.bridal;
  const bangles =
    o.kind === "lehenga"
      ? [palette.maroonLight, "#F4EEE2", palette.maroonLight, "#D9B46A", palette.maroonLight]
      : o.kind === "saree"
        ? [palette.maroonLight, "#D9B46A", palette.maroonLight]
        : undefined;
  const arm: ArmSpec = {
    sleeve: o.sleeve,
    cuff: o.cuff,
    kind: o.sleeveKind,
    pattern: o.sleevePattern,
    female,
    skin: p.skin,
    mehendi: bridal,
    bangles,
    pins,
  };
  const [lx, rx] = female ? [148, 252] : [132, 268];
  // Heads are drawn larger than life (≈6.5–7 heads tall) — the illustrated-catalogue charm.
  const hs = p.headScale ?? 1.3;

  return (
    <svg width={(height * 400) / 1000} height={height} viewBox="0 0 400 1000" style={{ overflow: "visible", ...style }}>
      <g transform={`translate(200 956) scale(${p.scale}) translate(-200 -956)`}>
        {layers.back}
        <g transform={`translate(200 206) scale(${hs}) translate(-200 -206)`}>
          <HeadBack p={p} />
        </g>
        {layers.body}
        <g transform={`translate(${lx} 238)`}>
          <Arm spec={arm} shoulder={ps.lShoulder} elbow={ps.lElbow} />
        </g>
        <g transform={`translate(${rx} 238) scale(-1 1)`}>
          <Arm spec={arm} shoulder={-ps.rShoulder} elbow={-ps.rElbow} held={holding ? HELD[holding] : undefined} flipHeld />
        </g>
        {layers.front}
        <g transform={`translate(200 206) scale(${hs}) rotate(${ps.headTilt}) translate(-200 -206)`}>
          <Head p={p} hideHairFront={o.kind === "sherwani" && !!o.safa}>
            {female ? <Earrings pearls={o.kind === "saree"} /> : null}
            {bridal ? <MaangTikka /> : null}
            {bridal ? <Nath /> : null}
            {o.kind === "sherwani" && o.safa ? <Safa color={o.safa.color} stripe={o.safa.stripe} /> : null}
            {o.kind === "sherwani" && o.safa && sehra > 0 ? <Sehra drop={sehra} /> : null}
            {o.kind === "lehenga" && o.veil ? <VeilFront color={o.veil} /> : null}
          </Head>
        </g>
      </g>
    </svg>
  );
};
